-- ===================== HISTORICAL JOB ORDERS =====================
-- row 2: Jetrich / 'Flex' / '5 x 6' / 6000.0
DO $$
DECLARE
  v_customer_id UUID;
  v_job_order_id UUID;
  v_invoice_id UUID;
  v_payment_id UUID;
  v_admin_id UUID;
BEGIN
  IF EXISTS (SELECT 1 FROM job_orders WHERE job_order_no = 'CLM/JO/20260108/001') THEN
    RETURN;
  END IF;
  SELECT id INTO v_customer_id FROM customers WHERE name = 'Jetrich';
  SELECT id INTO v_admin_id FROM users WHERE username = 'admin';

  INSERT INTO job_orders (customer_id, job_order_no, subtotal, amount_paid, outstanding_balance, payment_status, remark, created_by, created_at, updated_at)
  VALUES (v_customer_id, 'CLM/JO/20260108/001', 6000.0, 6000.0, 0, 'paid', 'Historical import from 2026 ledger', v_admin_id, '2026-01-08'::timestamp, '2026-01-08'::timestamp)
  RETURNING id INTO v_job_order_id;

  INSERT INTO job_order_items (job_order_id, category, material, description, size, width, height, quantity, unit, applied_rate, calculated_amount, remark)
  VALUES (v_job_order_id, 'Large Format', 'Flex', '5 x 6', '5 x 6', 5.0, 6.0, 1, 'unit', 6000.0, 6000.0, 'Historical import');

  INSERT INTO invoices (invoice_no, job_order_id, customer_id, subtotal, amount_paid, outstanding, status, created_at)
  VALUES ('CLM/INV/20260108/001', v_job_order_id, v_customer_id, 6000.0, 6000.0, 0, 'paid', '2026-01-08'::timestamp)
  RETURNING id INTO v_invoice_id;

  INSERT INTO payments (job_order_id, customer_id, amount, method, remark, created_by, created_at)
  VALUES (v_job_order_id, v_customer_id, 6000.0, 'Cash', 'Historical import', v_admin_id, '2026-01-08'::timestamp)
  RETURNING id INTO v_payment_id;

  INSERT INTO payment_allocations (payment_id, invoice_id, amount)
  VALUES (v_payment_id, v_invoice_id, 6000.0);

  INSERT INTO receipts (receipt_no, payment_id, customer_id, amount, created_at)
  VALUES ('CLM/RC/20260108/001', v_payment_id, v_customer_id, 6000.0, '2026-01-08'::timestamp);
END $$;

